const families:Record<string,string>={'caddy':'caddy','nginx':'nginx','php':'php','node':'nodedotjs','python':'python','go':'go','java':'openjdk','java-jre':'openjdk','bun':'bun','deno':'deno','dotnet-sdk':'dotnet','dotnet-runtime':'dotnet','aspnet-runtime':'dotnet','zig':'zig','nim':'nim','luau':'luau','wasmtime':'webassembly','mariadb':'mariadb','mongodb':'mongodb','duckdb':'duckdb','sqlite':'sqlite','traefik':'traefikproxy','frankenphp':'php','gleam':'gleam','pocketbase':'pocketbase','uv':'uv','pnpm':'pnpm','gh':'github','hugo':'hugo','typst':'typst','erlang':'erlang','perl':'perl','julia':'julia','nushell':'nushell','babashka':'clojure','gcc':'gnu','llvm-mingw':'llvm','dart':'dart','vlang':'v','odin':'odin','haxe':'haxe','tinygo':'go','cmake':'cmake'};
/** The product's logo for a catalog family, or '' when it has none. */
export function stackLogo(family:string):string {
 if(Object.hasOwn(custom,family))return custom[family];
 const shape=shapes[families[family]??''];
 if(!shape)return '';
 return `<svg class="stack-logo ${shape.plain.split(' ').filter(Boolean).map(t=>`plain-${t}`).join(' ')}" viewBox="0 0 24 24" aria-hidden="true"><path fill="${shape.color}" d="${shape.path}"/></svg>`;
}
